#define STR(x) #x
#define UNROLL(n) _Pragma(STR(GCC unroll n))

static inline void cpu_relax(void)
{
#if defined(__x86_64__) || defined(__i386__)
    __builtin_ia32_pause();
#elif defined(__aarch64__)
    __asm__ __volatile__("yield");
#endif
}

/* ---------------- microkernel ---------------- */

#ifdef NEON_KERNEL

static inline __attribute__((always_inline))
void kernel(int kc, const float *restrict a, const float *restrict b,
            float *restrict c, int ldc, int mr, int nr, int first)
{
    float32x4_t z = vdupq_n_f32(0.0f);
    float32x4_t c00 = z, c01 = z, c02 = z, c10 = z, c11 = z, c12 = z;
    float32x4_t c20 = z, c21 = z, c22 = z, c30 = z, c31 = z, c32 = z;
    float32x4_t c40 = z, c41 = z, c42 = z, c50 = z, c51 = z, c52 = z;
    float32x4_t c60 = z, c61 = z, c62 = z, c70 = z, c71 = z, c72 = z;

#define FROW(i, av, l)                                  \
    c##i##0 = vfmaq_laneq_f32(c##i##0, b0, av, l);      \
    c##i##1 = vfmaq_laneq_f32(c##i##1, b1, av, l);      \
    c##i##2 = vfmaq_laneq_f32(c##i##2, b2, av, l);
#define STEP                                                            \
    {                                                                   \
        float32x4_t a0 = vld1q_f32(a), a1 = vld1q_f32(a + 4);           \
        float32x4_t b0 = vld1q_f32(b), b1 = vld1q_f32(b + 4);           \
        float32x4_t b2 = vld1q_f32(b + 8);                              \
        FROW(0, a0, 0) FROW(1, a0, 1) FROW(2, a0, 2) FROW(3, a0, 3)     \
        FROW(4, a1, 0) FROW(5, a1, 1) FROW(6, a1, 2) FROW(7, a1, 3)     \
        a += MR; b += NR;                                               \
    }

    int p = 0;
    for (; p + 2 <= kc; p += 2) {
        STEP
        STEP
    }
    for (; p < kc; p++)
        STEP
#undef STEP
#undef FROW

    if (mr == MR && nr == NR) {
#define STF(i) { float *r = c + (size_t)(i) * ldc;                       \
        vst1q_f32(r, c##i##0); vst1q_f32(r + 4, c##i##1);                \
        vst1q_f32(r + 8, c##i##2); }
#define STA(i) { float *r = c + (size_t)(i) * ldc;                       \
        vst1q_f32(r, vaddq_f32(vld1q_f32(r), c##i##0));                  \
        vst1q_f32(r + 4, vaddq_f32(vld1q_f32(r + 4), c##i##1));          \
        vst1q_f32(r + 8, vaddq_f32(vld1q_f32(r + 8), c##i##2)); }
        if (first) {
            STF(0) STF(1) STF(2) STF(3) STF(4) STF(5) STF(6) STF(7)
        } else {
            STA(0) STA(1) STA(2) STA(3) STA(4) STA(5) STA(6) STA(7)
        }
#undef STF
#undef STA
    } else {
        float t[MR][NR] __attribute__((aligned(64)));
#define STT(i) vst1q_f32(&t[i][0], c##i##0); vst1q_f32(&t[i][4], c##i##1); \
        vst1q_f32(&t[i][8], c##i##2);
        STT(0) STT(1) STT(2) STT(3) STT(4) STT(5) STT(6) STT(7)
#undef STT
        for (int i = 0; i < mr; i++) {
            float *cr = c + (size_t)i * ldc;
            if (first)
                for (int j = 0; j < nr; j++) cr[j] = t[i][j];
            else
                for (int j = 0; j < nr; j++) cr[j] += t[i][j];
        }
    }
}

#else /* generic vector-extension kernel (x86 etc.) */

typedef float vf __attribute__((vector_size(VL * 4)));
typedef float vfu __attribute__((vector_size(VL * 4), aligned(4)));

static inline __attribute__((always_inline))
void kernel(int kc, const float *restrict a, const float *restrict b,
            float *restrict c, int ldc, int mr, int nr, int first)
{
    vf acc[MR][NV];
    UNROLL(16)
    for (int i = 0; i < MR; i++)
        UNROLL(4)
        for (int v = 0; v < NV; v++)
            acc[i][v] = (vf){0};

    UNROLL(16)
    for (int i = 0; i < MR; i++)
        __builtin_prefetch(c + (size_t)i * ldc, 1, 3);

    UNROLL(4)
    for (int p = 0; p < kc; p++) {
        vf bv[NV];
        UNROLL(4)
        for (int v = 0; v < NV; v++)
            bv[v] = *(const vf *)(b + v * VL);
        UNROLL(16)
        for (int i = 0; i < MR; i++) {
            float ai = a[i];
            UNROLL(4)
            for (int v = 0; v < NV; v++)
                acc[i][v] += ai * bv[v];
        }
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
        if (first) {
            UNROLL(16)
            for (int i = 0; i < MR; i++)
                UNROLL(4)
                for (int v = 0; v < NV; v++)
                    *(vfu *)(c + (size_t)i * ldc + v * VL) = acc[i][v];
        } else {
            UNROLL(16)
            for (int i = 0; i < MR; i++)
                UNROLL(4)
                for (int v = 0; v < NV; v++)
                    *(vfu *)(c + (size_t)i * ldc + v * VL) += acc[i][v];
        }
    } else {
        float t[MR][NR] __attribute__((aligned(64)));
        UNROLL(16)
        for (int i = 0; i < MR; i++)
            UNROLL(4)
            for (int v = 0; v < NV; v++)
                *(vf *)&t[i][v * VL] = acc[i][v];
        for (int i = 0; i < mr; i++) {
            float *cr = c + (size_t)i * ldc;
            if (first)
                for (int j = 0; j < nr; j++) cr[j] = t[i][j];
            else
                for (int j = 0; j < nr; j++) cr[j] += t[i][j];
        }
    }
}

